import{_ as a,C as i,o as r,c as o,j as t,a as n,E as l,a6 as u}from"./chunks/framework.CCKCzdWs.js";const b=JSON.parse('{"title":"Issues about a run or a test","description":"File a Jira issue about a whole Playwright run, or about one test that belongs to no failure cluster, with your own comment first in its body.","frontmatter":{"title":"Issues about a run or a test","description":"File a Jira issue about a whole Playwright run, or about one test that belongs to no failure cluster, with your own comment first in its body.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/run-issues.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/run-issues.html"}],["meta",{"property":"og:title","content":"Issues about a run or a test | Piwi for Playwright"}],["meta",{"property":"og:description","content":"File a Jira issue about a whole Playwright run, or about one test that belongs to no failure cluster, with your own comment first in its body."}]]},"headers":[],"relativePath":"features/run-issues.md","filePath":"features/run-issues.md","lastUpdated":1794590733000}'),h={name:"features/run-issues.md"};function c(d,e,f,m,g,w){const s=i("Needs");return r(),o("div",null,[e[0]||(e[0]=t("h1",{id:"issues-about-a-run-or-a-test",tabindex:"-1"},[n("Issues about a run or a test "),t("a",{class:"header-anchor",href:"#issues-about-a-run-or-a-test","aria-label":'Permalink to "Issues about a run or a test"'},"​")],-1)),l(s,{reporter:"",admin:""}),e[1]||(e[1]=u('<p>Not every finding is a failure Piwi groups: a test that passes but misses a case, a step too slow to be useful, a suite that passed while the feature is broken. <strong>Create issue</strong> also files those, through the same modal, connection and <a href="./issue-tracking.html#the-project-binding">project binding</a> as an issue about a failure.</p><h2 id="where-it-is" tabindex="-1">Where it is <a class="header-anchor" href="#where-it-is" aria-label="Permalink to &quot;Where it is&quot;">​</a></h2><ul><li><strong>On a run&#39;s page</strong>, the header&#39;s <strong>Create issue</strong> files an issue about the whole run.</li><li><strong>On an execution with no failure cluster</strong> (a passed or skipped test, or a failure not grouped), the <strong>More actions</strong> menu&#39;s <strong>Create issue</strong> files one about that test. An execution with a cluster files on its cluster, as <a href="./issue-tracking.html#what-it-does-exactly">Issue tracking</a> describes.</li></ul><h2 id="what-the-issue-holds" tabindex="-1">What the issue holds <a class="header-anchor" href="#what-the-issue-holds" aria-label="Permalink to &quot;What the issue holds&quot;">​</a></h2><ul><li><strong>Comment</strong> comes first: your own words, up to 5,000 characters, under your name. The modal offers it for a failure cluster&#39;s issue too; when the cluster already has its issue, the comment is added to that issue instead, and a later update of the issue&#39;s description keeps it first. The modal says whether the comment was added, is still queued, or was refused by Jira.</li><li><strong>A run&#39;s issue</strong> lists the run (project, branch, commit, environment, start), its results, its tests with failed ones first (25 listed, then a count), the failure clusters of its failures with the issue each one already has (the 10 with the most failures, then a count), links back to the run, and who filed it from Piwi. Its proposed title counts the failures and names the branch.</li><li><strong>A test&#39;s issue</strong> has the same body for that one test, titled after it, with its error when it failed.</li><li>Each carries the labels <code>piwi</code> and <code>piwi-run-&lt;id&gt;</code> and a <code>Piwi-Run: &lt;id&gt;</code> trailer, for JQL. A run&#39;s issue shows in the run&#39;s <strong>Links</strong>.</li><li>The body follows the <a href="./issue-tracking.html#language">ticket&#39;s language</a>. Only Piwi&#39;s own copy is translated, never your comment or the test data.</li></ul><h2 id="several-issues-each-filed-once" tabindex="-1">Several issues, each filed once <a class="header-anchor" href="#several-issues-each-filed-once" aria-label="Permalink to &quot;Several issues, each filed once&quot;">​</a></h2><p>A run, or a test with no cluster, <strong>can have several issues</strong>: the modal lists the ones already linked and files a new one. Each opening of the modal files at most one, so a second click on <strong>Create</strong>, or opening it again while a filing waits on Jira (after a reload too, or in another tab of the same browser, for a day), never files twice. Create sent again while that filing is still queued files it with what the modal holds now. Any create, a cluster&#39;s too, that Jira may have received without its answer coming back (a timeout, or the server restarted during the call) fails with <strong>Outcome unknown</strong> rather than risking a second issue: check Jira for it, then create it again if it is not there.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Filed by hand only</strong>: <a href="./issue-automation.html">Issue automation</a> rules file failure clusters, never a run or a test.</li><li>The body is a <strong>snapshot</strong> at creation; the <a href="./issue-tracking.html#keep-the-ticket-honest">write-back policies</a> follow clusters, not runs.</li><li>From an AI agent, the <a href="/reference/mcp-tools.html#create_issue"><code>create_issue</code> MCP tool</a> files about a cluster, an execution in a cluster or a bug report, one issue per cluster: never a whole run, nor a test with no cluster.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./issue-tracking.html">Issue tracking (Jira)</a>: issues about a failure cluster, the binding and the sync</li><li><a href="./issue-automation.html">Issue automation</a>: tickets filed by rule</li></ul>',11))])}const y=a(h,[["render",c]]);export{b as __pageData,y as default};
